  "source": "def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        table = {}
        committed = {}
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        in_tx = False
        tx_conn = None
        tx_snapshot = None

        def do_write(conn, op, key, value):
            nonlocal main_changes, other_changes, main_total, other_total
            changed = 0
            fired_trigger = False
            if op == "put":
                if key in table:
                    if put_mode == "ignore":
                        changed = 0
                    elif put_mode == "replace":
                        table[key] = value
                        changed = 1
                        fired_trigger = True
                    else:
                        table[key] = value
                        changed = 1
                        fired_trigger = True
                else:
                    table[key] = value
                    changed = 1
                    fired_trigger = True
            elif op == "update":
                if key in table:
                    table[key] = value
                    changed = 1
            elif op == "delete":
                if key in table:
                    del table[key]
                    changed = 1

            if trigger and fired_trigger:
                 changed += 1

            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_changes = changed
                other_total += changed

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            key = action.get("key")
            value = action.get("value")

            if op == "begin":
                if not in_tx:
                    in_tx = True
                    tx_conn = conn
                    tx_snapshot = (dict(table), dict(committed), main_changes, other_changes, main_total, other_total)
            elif op == "commit":
                if in_tx:
                    committed = dict(table)
                    in_tx = False
                    tx_conn = None
                    tx_snapshot = None
            elif op == "rollback":
                if in_tx:
                    table, committed, main_changes, other_changes, main_total, other_total = tx_snapshot
                    in_tx = False
                    tx_conn = None
                    tx_snapshot = None
            else:
                do_write(conn, op, key, value)

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total":
            channel = main_total
        else:
            channel = main_total + other_total
        return channel, len(committed), sum(committed.values())

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trigger in (False, True):
            for channel_mode in ("changes", "total", "both"):
                match = True
                for receipt in history:
                    acts = receipt.get("actions", [])
                    obs = receipt.get("observed", {})
                    ch, cc, cs = simulate(acts, put_mode, trigger, channel_mode)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        match = False
                        break
                if match:
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for pm, tr, cm in candidates:
        res = simulate(actions, pm, tr, cm)
        if goal == "channel":
            values.append(res[0])
        elif goal == "committed_count":
            values.append(res[1])
        elif goal == "committed_sum":
            values.append(res[2])
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}",
  "scope": "Disposable SQLite sources from the disclosed 18-member family, supporting put/update/delete/begin/commit/rollback on main/other connections, with goals channel, committed_count, or committed_sum.",
  "lesson": "The previous simulator incorrectly applied the AFTER INSERT trigger's row-count increment to all write operations (updates and deletes) whenever `changed > 0`. In SQLite, an AFTER INSERT trigger only fires upon successful insertion. The corrected model introduces a `fired_trigger` flag that is set exclusively during 'put' operations that result in an actual row modification (insertion or replacement/upsert). This ensures the auxiliary log insert count (+1) is added to the changes counter only when appropriate, resolving discrepancies where updates were previously overcounted."
}
